fn testa_dois_e_igual_a_dois() {
    assert_eq!(sao_iguais(2, 2), true);
}

#[test]
fn testa_dois_e_tres_nao_sao_iguais() {
    assert_eq!(sao_iguais(2, 3), false);
}

#[test]
fn testa_a_soma_dois_com_dois_igual_ao_produto() {
